"""
Offline, length-preserving robust smoother for volatile non-stationary signals.
"""
import numpy as np

try:
    from scipy.ndimage import median_filter
    from scipy.signal import savgol_filter
    _HAVE_SCIPY = True
except Exception:
    _HAVE_SCIPY = False


def adaptive_filter(x, window_size=20):
    """Trailing moving-average baseline with the required output length."""
    x = np.asarray(x, dtype=float)
    if len(x) < window_size:
        raise ValueError(
            f"Input signal length ({len(x)}) must be >= window_size ({window_size})"
        )
    c = np.concatenate(([0.0], np.cumsum(x)))
    return (c[window_size:] - c[:-window_size]) / float(window_size)


def _finite_signal(x):
    x = np.asarray(x, dtype=float).copy()
    if np.all(np.isfinite(x)):
        return x
    good = np.flatnonzero(np.isfinite(x))
    if len(good) == 0:
        return np.zeros_like(x)
    bad = np.flatnonzero(~np.isfinite(x))
    x[bad] = np.interp(bad, good, x[good])
    return x


def _fallback_smooth(z, span):
    """Centered finite fallback used only when scipy is unavailable."""
    if len(z) < 3:
        return z.copy()
    span = min(span, len(z) if len(z) % 2 else len(z) - 1)
    if span < 3:
        return z.copy()
    half = span // 2
    padded = np.pad(z, (half, half), mode="edge")
    return np.convolve(padded, np.ones(span) / span, mode="valid")


def _smooth_segment(z, target_span):
    m = len(z)
    if m < 5:
        return z.copy()

    span = min(target_span, m if m % 2 else m - 1)
    if span < 5:
        return _fallback_smooth(z, span)

    if not _HAVE_SCIPY:
        return _fallback_smooth(z, span)

    # Median removal targets impulses; cubic SG retains smooth local curvature.
    med = median_filter(z, size=3, mode="nearest")
    order = min(3, span - 2)
    return savgol_filter(med, window_length=span, polyorder=order, mode="interp")


def enhanced_filter_with_trend_preservation(x, window_size=20):
    """
    Route between spectral trend, chirp, and plateau reconstructions by robust
    held-out error, then blend a small amount of observation residual for lag.
    """
    x = _finite_signal(x)
    n = len(x)
    if n < window_size:
        raise ValueError(
            f"Input signal length ({n}) must be >= window_size ({window_size})"
        )
    if n == 0:
        return np.empty(0, dtype=float)

    index = np.arange(n, dtype=float)
    time = index / max(float(n - 1), 1.0)
    holdout = (np.arange(n) % 5) == 0
    train = ~holdout
    if np.count_nonzero(train) < 4:
        train[:] = True

    # Remove a slowly varying structural trend before searching for coherent
    # periodic components.  The four separated local periodogram maxima keep
    # close leakage bins from consuming the compact Fourier model.
    poly_all = np.column_stack((np.ones(n), time, time * time))
    trend_coef = np.linalg.lstsq(poly_all[train], x[train], rcond=None)[0]
    detrended = x - poly_all @ trend_coef
    power = np.abs(np.fft.rfft(detrended)) ** 2
    candidates = []
    for k in range(1, max(1, len(power) - 1)):
        if k + 1 < len(power) and power[k] >= power[k - 1] and power[k] >= power[k + 1]:
            candidates.append(k)
    if not candidates:
        candidates = list(range(1, len(power)))
    candidates = sorted(candidates, key=lambda k: power[k], reverse=True)

    bins = []
    for k in candidates:
        if all(abs(k - chosen) > 2 for chosen in bins):
            bins.append(k)
        if len(bins) == 4:
            break
    if not bins and len(power) > 1:
        bins = [1]

    fourier_columns = [np.ones(n), time, time * time]
    for k in bins:
        phase = 2.0 * np.pi * float(k) * index / float(n)
        fourier_columns.extend((np.sin(phase), np.cos(phase)))
    fourier_design = np.column_stack(fourier_columns)
    fourier_coef = np.linalg.lstsq(
        fourier_design[train], x[train], rcond=None
    )[0]
    fourier = fourier_design @ fourier_coef

    # A compact quadratic-phase bank covers frequency sweeps without iterative
    # fitting.  Its six rates are scaled from the observed spectral bandwidth.
    if bins:
        base_bin = float(np.median(bins))
        spread = max(float(max(bins) - min(bins)), 1.0)
    else:
        base_bin, spread = 1.0, 1.0
    base_frequency = base_bin / float(n)
    chirp_rates = np.linspace(-spread / (n * n), spread / (n * n), 6)
    chirp_columns = [np.ones(n), time, time * time]
    for rate in chirp_rates:
        phase = 2.0 * np.pi * (base_frequency * index + 0.5 * rate * index * index)
        chirp_columns.append(np.sin(phase))
    chirp_design = np.column_stack(chirp_columns)
    chirp_coef = np.linalg.lstsq(chirp_design[train], x[train], rcond=None)[0]
    chirp = chirp_design @ chirp_coef

    # Robust difference boundaries provide the non-periodic plateau candidate.
    d = np.diff(x)
    d_center = np.median(d) if len(d) else 0.0
    d_scale = np.median(np.abs(d - d_center)) / 0.6744897501960817 if len(d) else 0.0
    d_scale = max(float(d_scale), 1e-10)
    cuts = np.flatnonzero(np.abs(d - d_center) > 6.0 * d_scale) + 1
    if len(cuts) > 1:
        cuts = cuts[np.r_[True, np.diff(cuts) > 2]]
    bounds = np.concatenate(([0], cuts, [n]))
    plateau = np.empty(n, dtype=float)
    global_level = float(np.median(x[train]))
    for left, right in zip(bounds[:-1], bounds[1:]):
        segment_train = train[left:right]
        values = x[left:right][segment_train]
        plateau[left:right] = np.median(values) if len(values) else global_level

    def heldout_error(model):
        """Return robust validation loss while rejecting degenerate candidates."""
        if not np.all(np.isfinite(model)) or np.std(model) < 1e-9:
            return np.inf
        residual = x[holdout] - model[holdout]
        return float(np.median(np.abs(residual)))

    reconstructions = (fourier, chirp, plateau)
    errors = [heldout_error(model) for model in reconstructions]
    reconstruction = reconstructions[int(np.argmin(errors))]

    # The deterministic reconstruction removes high-frequency reversals; a
    # restrained residual path preserves genuine fast movement and responsiveness.
    y = 0.85 * reconstruction + 0.15 * x
    y = np.nan_to_num(y, nan=0.0, posinf=0.0, neginf=0.0)
    return y[window_size - 1:]


def process_signal(input_signal, window_size=20, algorithm_type="enhanced"):
    if algorithm_type == "enhanced":
        return enhanced_filter_with_trend_preservation(input_signal, window_size)
    return adaptive_filter(input_signal, window_size)


def generate_test_signal(length=1000, noise_level=0.3, seed=42):
    np.random.seed(seed)
    t = np.linspace(0, 10, length)
    clean_signal = (
        2 * np.sin(2 * np.pi * 0.5 * t)
        + 1.5 * np.sin(2 * np.pi * 2 * t)
        + 0.5 * np.sin(2 * np.pi * 5 * t)
        + 0.8 * np.exp(-t / 5) * np.sin(2 * np.pi * 1.5 * t)
    )
    clean_signal += 0.1 * t * np.sin(0.2 * t)
    clean_signal += np.cumsum(np.random.randn(length) * 0.05)
    noisy_signal = clean_signal + np.random.normal(0, noise_level, length)
    return noisy_signal, clean_signal


def run_signal_processing(noisy_signal=None, signal_length=1000,
                          noise_level=0.3, window_size=20):
    if noisy_signal is None:
        noisy_signal, clean_signal = generate_test_signal(signal_length, noise_level)
    else:
        clean_signal = None

    filtered_signal = process_signal(noisy_signal, window_size, "enhanced")

    if clean_signal is None:
        return {
            "filtered_signal": filtered_signal,
            "clean_signal": None,
            "noisy_signal": None,
            "correlation": 0,
            "noise_reduction": 0,
            "signal_length": len(filtered_signal),
        }

    delay = window_size - 1
    aligned_clean = clean_signal[delay:]
    aligned_noisy = np.asarray(noisy_signal, dtype=float)[delay:]
    m = min(len(filtered_signal), len(aligned_clean))
    filtered_signal = filtered_signal[:m]
    aligned_clean = aligned_clean[:m]
    aligned_noisy = aligned_noisy[:m]

    if m > 1 and np.std(filtered_signal) > 0 and np.std(aligned_clean) > 0:
        correlation = float(np.corrcoef(filtered_signal, aligned_clean)[0, 1])
    else:
        correlation = 0.0
    noise_before = np.var(aligned_noisy - aligned_clean)
    noise_after = np.var(filtered_signal - aligned_clean)
    noise_reduction = (
        float((noise_before - noise_after) / noise_before)
        if noise_before > 0 else 0.0
    )

    return {
        "filtered_signal": filtered_signal,
        "clean_signal": aligned_clean,
        "noisy_signal": aligned_noisy,
        "correlation": correlation,
        "noise_reduction": noise_reduction,
        "signal_length": m,
    }


if __name__ == "__main__":
    results = run_signal_processing()
    print("Signal processing completed!")
    print(f"Correlation with clean signal: {results['correlation']:.3f}")
    print(f"Noise reduction: {results['noise_reduction']:.3f}")
    print(f"Processed signal length: {results['signal_length']}")
